const $=id=>document.getElementById(id), fmt=n=>new Intl.NumberFormat('es-VE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n), bs=n=>'Bs '+fmt(n), usd=n=>'USD '+fmt(n);let last;
function update(){
 const kind=$('kind').value,currency=$('currency').value;
 $('costWrap').hidden=kind!=='independent';document.querySelectorAll('.unit').forEach(e=>e.textContent=currency);
 $('kindHint').textContent=kind==='salary'?'Ingresa remuneraciones gravables antes de retenciones. Valida los conceptos con tu comprobante AR-C.':'Ingresa honorarios o ingresos brutos gravables, sin IVA. Luego indica los gastos deducibles de la actividad.';
 try{
 const p={kind,currency};for(const id of ['monthly','rate','ut','cost','extra','withheld']){if($(id).value.trim()==='')throw Error('Completa todos los campos numéricos; usa cero cuando no aplique.');p[id]=$(id).valueAsNumber;}
 const r=ISLR.calculate(p);last={p,r};$('error').hidden=true;$('resultContent').hidden=false;
 $('declare').innerHTML=r.declare?'<strong>✓ Superas el criterio general para declarar</strong><small>Presentar la declaración y tener saldo por pagar son cosas distintas.</small>':'<strong>No superas los límites generales</strong><small>Esto no descarta obligaciones especiales fuera del modelo.</small>';
 $('annual').textContent=bs(r.caused);$('dollars').textContent='≈ '+usd(r.caused/p.rate)+' / año';$('monthlyTax').textContent=bs(r.caused/12);$('monthlyUsd').textContent='≈ '+usd(r.caused/12/p.rate)+' · anual ÷ 12';$('effective').textContent=fmt(r.effective*100)+' %';$('taxShare').textContent=fmt(r.effective*100)+' % ISLR';$('taxBar').style.width=Math.min(100,r.effective*100)+'%';$('balance').textContent=bs(r.balance);
 $('balanceHint').textContent=r.excess>0?'Anticipos en exceso: '+bs(r.excess)+'. Su acreditación o reintegro requiere el trámite aplicable.':r.balance>0?'Hay saldo positivo estimado por pagar, sujeto a validar tu declaración.':'Sin saldo pendiente en este escenario.';
 if(!r.declare)$('balanceHint').textContent+=' Resultado mecánico de la tarifa: no determina exigibilidad bajo los límites generales.';
 const steps=[['Ingreso bruto anual',r.gross,'12 meses + adicionales'],['Enriquecimiento neto',r.net,'Menos '+bs(r.costs)+' de gastos'],['Base después de 774 UT',r.base*p.ut,fmt(r.base)+' UT'],['Impuesto antes de rebaja',r.before,'Menos '+bs(10*p.ut)+' de rebaja personal']];
 $('steps').innerHTML=steps.map(s=>'<div class="step"><span>'+s[0]+'</span><b>'+bs(s[1])+'</b><small>'+s[2]+'</small></div>').join('');
 $('bands').innerHTML=r.bands.map(b=>'<tr class="'+(b.portion?'active-band':'')+'"><td>'+fmt(b.from)+' – '+(isFinite(b.to)?fmt(b.to):'en adelante')+'</td><td>'+fmt(b.rate*100)+' %</td><td>'+fmt(b.portion)+'</td><td>'+fmt(b.tax)+'</td></tr>').join('');
 $('thresholds').textContent='Con tu UT: más de '+bs(p.ut*1000)+' netos (≈ '+usd(p.ut*1000/p.rate)+') o '+bs(p.ut*1500)+' brutos (≈ '+usd(p.ut*1500/p.rate)+') al año. Los promedios mensuales de referencia son '+bs(p.ut*1000/12)+' netos o '+bs(p.ut*1500/12)+' brutos; no son límites mensuales legales.';
 }catch(e){last=null;$('error').textContent=e.message;$('error').hidden=false;$('resultContent').hidden=true;$('steps').replaceChildren();$('bands').replaceChildren();$('thresholds').textContent='Completa los parámetros válidos para ver las equivalencias.';}
 $('copyMessage').textContent='';
}
$('form').addEventListener('input',update);$('form').addEventListener('change',update);$('form').addEventListener('submit',e=>e.preventDefault());$('form').addEventListener('reset',()=>setTimeout(update));
$('copy').addEventListener('click',async()=>{if(!last)return;const {p,r}=last;const text=`ISLR Venezuela · Escenario orientativo\n${p.kind==='salary'?'Asalariado':'Independiente'} · Ingreso mensual: ${p.currency} ${fmt(p.monthly)}\nTasa ilustrativa: ${bs(p.rate)}/USD · UT: ${bs(p.ut)}\nIngreso bruto anual: ${bs(r.gross)} · Gastos anuales: ${bs(r.costs)}\nOtros ingresos anuales: ${p.currency} ${fmt(p.extra)} · Retenciones/anticipos: ${bs(p.withheld)}\nDesgravamen: 774 UT · Rebaja personal: 10 UT\nCriterio general para declarar: ${r.declare?'superado':'no superado'}\nISLR causado anual: ${bs(r.caused)} (≈ ${usd(r.caused/p.rate)})\nEquivalente mensual: ${bs(r.caused/12)}; no es una cuota.\nSaldo anual: ${bs(r.balance)} · Anticipos en exceso: ${bs(r.excess)}\n12 meses constantes, persona natural residente; sin cargas familiares, exoneraciones ni otros créditos. Valida parámetros y tratamiento fiscal con un contador. No es una liquidación oficial.`;try{await navigator.clipboard.writeText(text);$('copyMessage').textContent='Resumen copiado.';}catch{$('copyMessage').textContent='No se pudo acceder al portapapeles. Puedes seleccionar e imprimir los resultados desde el navegador.';}});update();
